import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import '../services/openai_service.dart';
import 'ai_settings_screen.dart';
class MentorScreen extends StatefulWidget{const MentorScreen({super.key});@override State<MentorScreen> createState()=>_MentorScreenState();}
class _MentorScreenState extends State<MentorScreen>{final input=TextEditingController();String name='Aspirant',exam='Exam',language='Bengali';double hours=3;List<String> weak=[];int correct=0,total=0,mistakes=0;bool sending=false;final messages=<Map<String,String>>[];
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();name=p.getString('name')??'Aspirant';exam=p.getString('exam')??'Exam';language=p.getString('language')??'Bengali';hours=p.getDouble('daily_hours')??3;final selected=p.getStringList('weak_subjects')??[];final detected=p.getStringList('detected_weak_subjects')??[];weak=[...detected,...selected.where((x)=>!detected.contains(x))];correct=p.getInt('last_mock_correct')??0;total=p.getInt('last_mock_total')??0;mistakes=(p.getStringList('mistake_book')??[]).length;if(mounted)setState(()=>messages.add({'role':'mentor','text':'AgenticAI V2 online mentor ready. Ask anything about your '+exam+' preparation.'}));}
 int get accuracy=>total==0?0:(correct/total*100).round();
 Future<void> send()async{final q=input.text.trim();if(q.isEmpty||sending)return;setState((){messages.add({'role':'user','text':q});sending=true;});input.clear();try{if(!await OpenAIService.configured()){if(mounted){setState(()=>sending=false);Navigator.push(context,MaterialPageRoute(builder:(_)=>const AISettingsScreen()));}return;}final prompt='Student: '+name+'\nTarget exam: '+exam+'\nPreferred language: '+language+'\nDaily study hours: '+hours.toStringAsFixed(1)+'\nLast mock: '+correct.toString()+'/'+total.toString()+' correct, '+accuracy.toString()+'% accuracy\nWeak subjects: '+(weak.isEmpty?'unknown':weak.join(', '))+'\nMistake book items: '+mistakes.toString()+'\n\nStudent question: '+q+'\nGive personalised, actionable exam guidance. For factual current-affairs questions use web search and mention dates when useful.';final ans=await OpenAIService.ask(input:prompt,webSearch:true);if(mounted)setState(()=>messages.add({'role':'mentor','text':ans}));}catch(e){if(mounted)setState(()=>messages.add({'role':'mentor','text':'Online AI error: '+e.toString()+'\nCheck your API key/internet and try again.'}));}finally{if(mounted)setState(()=>sending=false);}}
 @override void dispose(){input.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,8),child:Row(children:[const CircleAvatar(child:Icon(Icons.auto_awesome_rounded)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Online AI Mentor V2',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(exam+' • '+accuracy.toString()+'% accuracy')])),IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AISettingsScreen())),icon:const Icon(Icons.settings_rounded))])),Expanded(child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(c,i){final m=messages[i],mine=m['role']=='user';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:340),margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(18)),child:Text(m['text']!)));})),if(sending)const LinearProgressIndicator(),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Ask your real AI mentor...',border:OutlineInputBorder()))),const SizedBox(width:8),IconButton.filled(onPressed:sending?null:send,icon:const Icon(Icons.send_rounded))])))]);
}
